//! RR-T8d content keys and DPI × LOD scale against the RUNNING web code
//! (`tests/fixtures/atlas/atlas_keys.json`, generated by `gen.sh` from pin
//! `edb8fb56` + three@0.169.0; see `tests/fixtures/atlas/README.md`).
//!
//! Every expected value is a string or a binary64 produced by the web
//! function itself; comparison is exact (`==` on strings, `to_bits` on
//! numbers). Zero tolerance, zero allowed mismatches.

mod atlas_json;

use std::collections::BTreeSet;

use atlas_json::{load, Json};
use civ_renderer::assets::{Assets, CachePolicy, FakeGpu, FakeResource, ResourceKind};
use civ_renderer::core::zoom_lod::{city_badge_lod_level_for_dist, city_badge_lod_texture_scale};
use civ_renderer::raster::atlas::cache::TextureCache;
use civ_renderer::raster::atlas::keys::{
    city_badge_lod_segment, city_map_badge_key, city_map_badge_key_legacy, civ_sigil_cache_key,
    format_city_growth_percent_label, leader_portrait_cache_key, owner_emblem_key,
    prod_icon_cache_key, upgrade_badge_key, worker_sprite_cache_key, BadgePath, CityMapBadgeInput,
    OwnerEmblemContext,
};
use civ_renderer::raster::atlas::scale::{
    badge_canvas_px, badge_canvas_scale, badge_pixel_ratio, BADGE_MAX_CSS_WIDTH, MAX_TEXTURE_SIZE,
};

fn data() -> Json {
    let j = load("atlas_keys.json");
    assert_eq!(j.get("pin").str(), "edb8fb56");
    assert_eq!(j.get("three").str(), "0.169.0");
    j
}

fn input_of(j: &Json) -> CityMapBadgeInput {
    CityMapBadgeInput {
        city_name: j.get("cityName").str().to_owned(),
        population: j.get("population").bits(),
        defense_tier: u8::try_from(j.get("defenseTier").u32()).expect("tier"),
        civ_icon_id: j.get("civIconId").str().to_owned(),
        prod_active: j.get("prodActive").bool(),
        prod_kind: j.get("prodKind").opt_str().map(str::to_owned),
        prod_id: j.get("prodId").opt_str().map(str::to_owned),
        growth_percent: j.get("growthPercent").opt_bits(),
        growth_starving: j.get("growthStarving").bool(),
        resource_warning: j.get("resourceWarning").bool(),
        hover_expanded: j.get("hoverExpanded").bool(),
        is_city_state: j.get("isCityState").bool(),
        era: j.get("era").opt_bits(),
        is_capital: j.get("isCapital").bool(),
        lod_level: j.get("lodLevel").opt_bits(),
        ..CityMapBadgeInput::default()
    }
}

fn check(section: &str, mismatches: &[String], total: usize) {
    assert!(total > 0, "{section}: no vectors");
    assert!(
        mismatches.is_empty(),
        "{section}: {}/{total} mismatches, first: {:?}",
        mismatches.len(),
        &mismatches[..mismatches.len().min(5)]
    );
    eprintln!("{section}: {total}/{total} exact");
}

#[test]
fn city_map_badge_key_matches_web() {
    let j = data();
    let v = j.get("badgeKeys").arr();
    let mut bad = Vec::new();
    for e in v {
        let got = city_map_badge_key(&input_of(e.get("input")));
        let exp = e.get("key").str();
        if got != exp {
            bad.push(format!("{got:?} != {exp:?}"));
        }
    }
    check("cityMapBadgeKey", &bad, v.len());
    // The vector set really covers the JS edge cases.
    let keys: BTreeSet<&str> = v.iter().map(|e| e.get("key").str()).collect();
    assert!(keys.len() > 1000, "distinct keys {}", keys.len());
    assert!(keys.iter().any(|k| k.contains("|Infinity|")), "pop ∞");
    assert!(keys.iter().any(|k| k.contains("e1e+21")), "era 1e21");
    assert!(
        keys.iter().any(|k| k.contains("\u{2212}")),
        "negative growth"
    );
}

#[test]
fn legacy_key_matches_web() {
    let j = data();
    let v = j.get("legacyKeys").arr();
    let mut bad = Vec::new();
    for e in v {
        let got = city_map_badge_key_legacy(e.get("name").str(), e.get("population").opt_bits());
        if got != e.get("key").str() {
            bad.push(format!("{got:?} != {:?}", e.get("key").str()));
        }
    }
    check("cityMapBadgeKey(name, pop)", &bad, v.len());
}

#[test]
fn growth_label_matches_web() {
    let j = data();
    let v = j.get("growthLabels").arr();
    let mut bad = Vec::new();
    for e in v {
        let pct = e.get("pct").bits();
        let got = format_city_growth_percent_label(pct, e.get("starving").bool());
        if got != e.get("label").str() {
            bad.push(format!("{pct:e}: {got:?} != {:?}", e.get("label").str()));
        }
    }
    check("formatCityGrowthPercentLabel", &bad, v.len());
}

#[test]
fn related_keys_match_web() {
    let j = data();
    let mut bad = Vec::new();
    let mut n = 0;
    for e in j.get("sigilKeys").arr() {
        n += 1;
        let got = civ_sigil_cache_key(e.get("civ").str());
        if got != e.get("key").str() {
            bad.push(format!("sigil {got:?} != {:?}", e.get("key").str()));
        }
    }
    for e in j.get("portraitKeys").arr() {
        n += 1;
        let got = leader_portrait_cache_key(e.get("civ").str(), e.get("era").bits());
        if got != e.get("key").str() {
            bad.push(format!("portrait {got:?} != {:?}", e.get("key").str()));
        }
    }
    for e in j.get("prodKeys").arr() {
        n += 1;
        let got = prod_icon_cache_key(e.get("kind").str(), e.get("id").opt_str());
        if got != e.get("key").str() {
            bad.push(format!("prod {got:?} != {:?}", e.get("key").str()));
        }
    }
    for e in j.get("emblemKeys").arr() {
        n += 1;
        let ctx = OwnerEmblemContext {
            civ_id: e.get("civId").opt_str().map(str::to_owned),
            era: e.get("era").bits(),
            is_city_state: e.get("isCityState").bool(),
            is_barbarian: e.get("isBarbarian").bool(),
        };
        let got = owner_emblem_key(&ctx);
        if got != e.get("key").str() {
            bad.push(format!("emblem {got:?} != {:?}", e.get("key").str()));
        }
    }
    for e in j.get("workerKeys").arr() {
        n += 1;
        let got = worker_sprite_cache_key(e.get("owner").bits(), e.get("player").bits());
        if got != e.get("key").str() {
            bad.push(format!("worker {got:?} != {:?}", e.get("key").str()));
        }
    }
    for e in j.get("upgradeKeys").arr() {
        n += 1;
        let path = match e.get("path").str() {
            "armor" => BadgePath::Armor,
            "soft" => BadgePath::Soft,
            other => panic!("path {other}"),
        };
        let level = u8::try_from(e.get("level").u32()).expect("level");
        let got = upgrade_badge_key(path, level);
        if got != e.get("key").str() {
            bad.push(format!("upgrade {got:?} != {:?}", e.get("key").str()));
        }
    }
    check(
        "related keys (sigil/portrait/prod/emblem/worker/upgrade)",
        &bad,
        n,
    );
}

#[test]
fn lod_and_scale_match_web() {
    let j = data();
    let mut bad = Vec::new();
    let mut n = 0;
    for e in j.get("lodForDist").arr() {
        n += 1;
        let d = e.get("dist").bits();
        let got = u32::from(city_badge_lod_level_for_dist(d).as_u8());
        if got != e.get("level").u32() {
            bad.push(format!("lodForDist({d}) {got}"));
        }
    }
    for e in j.get("lodScale").arr() {
        n += 1;
        let got = city_badge_lod_texture_scale(e.get("level").bits());
        if got.to_bits() != e.get("scale").num().to_bits() {
            bad.push(format!("lodScale {got}"));
        }
    }
    for e in j.get("lodSegment").arr() {
        n += 1;
        let got = u32::from(city_badge_lod_segment(e.get("level").opt_bits()));
        if got != e.get("seg").u32() {
            bad.push(format!("lodSegment {got}"));
        }
    }
    assert_eq!(
        badge_pixel_ratio(None).to_bits(),
        j.get("noWindowRatio").bits().to_bits(),
        "no window"
    );
    for e in j.get("ratios").arr() {
        n += 1;
        let dpr = e.get("dpr").bits();
        let got = badge_pixel_ratio(Some(dpr));
        if got.to_bits() != e.get("ratio").bits().to_bits() {
            bad.push(format!("ratio({dpr}) {got}"));
        }
    }
    for e in j.get("scales").arr() {
        n += 1;
        let dpr = e.get("dpr").bits();
        let lod = e.get("lod").opt_bits();
        let got = badge_canvas_scale(Some(dpr), lod);
        if got.to_bits() != e.get("scale").bits().to_bits() {
            bad.push(format!("scale({dpr}, {lod:?}) {got}"));
        }
    }
    let mut unclamped = 0;
    for e in j.get("canvasSizes").arr() {
        n += 1;
        let dpr = e.get("dpr").bits();
        let lod = e.get("lod").opt_bits();
        let (w, h) = (e.get("w").num(), e.get("h").num());
        let px = badge_canvas_px(w, h, Some(dpr), lod);
        let (cw, ch) = (e.get("cw").u32(), e.get("ch").u32());
        let web_fits = cw <= MAX_TEXTURE_SIZE && ch <= MAX_TEXTURE_SIZE;
        if web_fits {
            unclamped += 1;
            if (px.width, px.height, px.clamped) != (cw, ch, false) {
                bad.push(format!(
                    "size {w}x{h} dpr {dpr} lod {lod:?}: {px:?} != {cw}x{ch}"
                ));
            }
        } else if !(px.clamped && px.width <= MAX_TEXTURE_SIZE && px.height <= MAX_TEXTURE_SIZE) {
            bad.push(format!("over-limit {w}x{h}: {px:?}"));
        }
        // Reachable badges (W ≤ 463 CSS px) never hit the ceiling.
        if w <= f64::from(BADGE_MAX_CSS_WIDTH) {
            assert!(
                web_fits && !px.clamped,
                "reachable badge clamped: {w}x{h} {px:?}"
            );
        }
    }
    assert!(unclamped > 1000);
    check("LOD / DPI / canvas size", &bad, n);
}

#[test]
fn lod_purge_matches_web() {
    // `disposeCityMapBadgeTexturesForOtherLod` ran on a Map of fake textures:
    // same freed count and the same surviving key set (order: the web Map
    // keeps insertion order, the Rust index is sorted — compared as sets).
    let j = data();
    let v = j.get("purge").arr();
    let fake = FakeGpu::new();
    for e in v {
        let assets: Assets<FakeResource> = Assets::new();
        let mut cache = TextureCache::new(&assets, CachePolicy::UNBOUNDED);
        for k in e.get("keys").arr() {
            let k = k.str();
            drop(
                cache
                    .acquire(k, || {
                        (k.to_owned(), 1, fake.alloc(ResourceKind::Texture, 1))
                    })
                    .expect("acquire"),
            );
        }
        let lod = e.get("lod").bits();
        let freed = cache.purge_other_lod(Some(lod));
        assert_eq!(freed as u32, e.get("freed").u32(), "freed for lod {lod}");
        let kept: BTreeSet<&str> = e.get("kept").arr().iter().map(Json::str).collect();
        let got: BTreeSet<&str> = cache.keys().collect();
        assert_eq!(got, kept, "kept for lod {lod}");
        let disposed: BTreeSet<&str> = e.get("disposed").arr().iter().map(Json::str).collect();
        assert_eq!(disposed.len(), freed);
        drop(cache);
        assets.flush().expect("flush");
    }
    eprintln!(
        "disposeCityMapBadgeTexturesForOtherLod: {}/{} exact",
        v.len(),
        v.len()
    );
    assert_eq!(fake.live_total(), 0, "every fake texture freed");
}
